package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A period of a sheet: its name, unique on the sheet, and its from and to dates, inclusive. A
 *  closed period keeps the due-total it had when it was closed (`closedTotal`). A soft-closed one
 *  (`closed` and `soft`) keeps it too, but claims dated in it can still be changed. */
public record Period(String sheetId, String name, LocalDate from, LocalDate to, boolean closed, BigDecimal closedTotal,
        boolean soft) {

    public Period(String sheetId, String name, LocalDate from, LocalDate to, boolean closed, BigDecimal closedTotal) {
        this(sheetId, name, from, to, closed, closedTotal, false);
    }

    /** A new, open period. */
    public Period(String sheetId, String name, LocalDate from, LocalDate to) {
        this(sheetId, name, from, to, false, null);
    }

    /** Whether the period is closed outright, not soft-closed: no claim dated in it can change. */
    public boolean hardClosed() {
        return closed && !soft;
    }

    /** Whether the two periods share a day. */
    public boolean overlaps(Period other) {
        return !from.isAfter(other.to) && !other.from.isAfter(to);
    }

    /** Whether the date falls in the period. */
    public boolean contains(LocalDate date) {
        return !date.isBefore(from) && !date.isAfter(to);
    }
}
package net.officefloor.hq.app.period;

/** Body of a new period: its name, its from and to dates (yyyy-mm-dd) and who adds it. */
public record PeriodRequest(String name, String from, String to, String user) {
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** A period needs a name and two dates, from on or before to. */
public class ValidatePeriod {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody PeriodRequest request,
            Out<PeriodRequest> body, Out<Period> period) throws InvalidSheetRequestException {
        String name = request == null || request.name() == null ? "" : request.name().trim();
        if (name.isEmpty()) {
            throw new InvalidSheetRequestException("A period needs a name");
        }
        LocalDate from = date(request.from());
        LocalDate to = date(request.to());
        if (from.isAfter(to)) {
            throw new InvalidSheetRequestException("A period's from-date must be on or before its to-date");
        }
        body.set(request);
        period.set(new Period(sheetId, name, from, to));
    }

    private static LocalDate date(String raw) throws InvalidSheetRequestException {
        String value = raw == null ? "" : raw.trim();
        try {
            return LocalDate.parse(value);
        } catch (DateTimeParseException e) {
            throw new InvalidSheetRequestException("Not a date (yyyy-mm-dd): " + value);
        }
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Val;

/** Adds the period unless the sheet already has one of its name or one sharing a day with it. */
public class SavePeriod {
    public void save(@Val Period period, Periods periods) throws InvalidSheetRequestException {
        for (Period other : periods.onSheet(period.sheetId())) {
            if (other.name().equals(period.name())) {
                throw new InvalidSheetRequestException("There is already a period named " + period.name());
            }
            if (other.overlaps(period)) {
                throw new InvalidSheetRequestException("The period overlaps " + other.name());
            }
        }
        periods.add(period);
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Runs after the period is saved, so a refused one writes no audit line. */
public class RecordPeriodAdded {
    public void record(@Val PeriodRequest request, @Val Period period, Audit audit) {
        audit.record("PERIOD_ADDED sheet=" + period.sheetId() + " by=" + request.user()
                + " period=" + period.name() + " from=" + period.from() + " to=" + period.to());
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.Map;

/** A period as the screen sees it: its dates as yyyy-mm-dd, whether it is closed and, when it is,
 *  the due-total fixed when it was closed and each person's (`closedPersonTotals`, by person id;
 *  a person not in it shows 0.00), and whether the close is a soft close. */
public record PeriodResponse(String name, String from, String to, boolean closed, String closedTotal,
        Map<String, String> closedPersonTotals, boolean soft) {
    public static PeriodResponse from(Period period) {
        return from(period, Map.of());
    }

    public static PeriodResponse from(Period period, Map<Long, BigDecimal> personTotals) {
        Map<String, String> totals = new LinkedHashMap<>();
        personTotals.forEach((id, total) -> totals.put(id.toString(), total.setScale(2).toPlainString()));
        return new PeriodResponse(period.name(), period.from().toString(), period.to().toString(), period.closed(),
                period.closedTotal() == null ? null : period.closedTotal().setScale(2).toPlainString(), totals,
                period.soft());
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.sql.Date;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The periods of each sheet. */
@Repository
public class Periods {

    private static final String COLUMNS = "SELECT sheet_id, name, from_date, to_date, closed, closed_total, soft FROM period";

    private final JdbcTemplate jdbc;

    public Periods(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every period on the sheet, by from-date. */
    public List<Period> onSheet(String sheetId) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? ORDER BY from_date", Periods::period, sheetId);
    }

    /** The period of this name on this sheet, or null when there is none. Locks its row for the
     *  rest of the transaction. */
    public Period find(String sheetId, String name) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? AND name = ? FOR UPDATE", Periods::period, sheetId, name)
                .stream().findFirst().orElse(null);
    }

    /** The (not soft-) closed period of the sheet whose dates contain the date, or null when there is none. */
    public Period closedOn(String sheetId, LocalDate date) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? AND closed AND NOT soft AND from_date <= ? AND to_date >= ?",
                Periods::period, sheetId, Date.valueOf(date), Date.valueOf(date)).stream().findFirst().orElse(null);
    }

    /** The soft-closed period of the sheet whose dates contain the date, or null when there is none. */
    public Period softClosedOn(String sheetId, LocalDate date) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? AND closed AND soft AND from_date <= ? AND to_date >= ?",
                Periods::period, sheetId, Date.valueOf(date), Date.valueOf(date)).stream().findFirst().orElse(null);
    }

    public void add(Period period) {
        jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date) VALUES (?, ?, ?, ?)",
                period.sheetId(), period.name(), Date.valueOf(period.from()), Date.valueOf(period.to()));
    }

    /** Close (or, when `soft`, soft-close) the period, fixing its due-total and each person's (by
     *  person id) afresh. */
    public void close(Period period, BigDecimal total, Map<Long, BigDecimal> personTotals, boolean soft) {
        jdbc.update("UPDATE period SET closed = TRUE, soft = ?, closed_total = ? WHERE sheet_id = ? AND name = ?",
                soft, total, period.sheetId(), period.name());
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND period_name = ?",
                period.sheetId(), period.name());
        personTotals.forEach((personId, personTotal) -> jdbc.update(
                "INSERT INTO period_person_total (sheet_id, period_name, person_id, total) VALUES (?, ?, ?, ?)",
                period.sheetId(), period.name(), personId, personTotal));
    }

    /** Each person's due-total fixed when the period was closed, by person id; empty while it is open. */
    public Map<Long, BigDecimal> personTotals(Period period) {
        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
        jdbc.query("SELECT person_id, total FROM period_person_total WHERE sheet_id = ? AND period_name = ?"
                + " ORDER BY person_id", rs -> {
                    totals.put(rs.getLong("person_id"), rs.getBigDecimal("total"));
                }, period.sheetId(), period.name());
        return totals;
    }

    /** Reopen the period: its due-total, and each person's, is live again. */
    public void reopen(Period period) {
        jdbc.update("UPDATE period SET closed = FALSE, soft = FALSE, closed_total = NULL WHERE sheet_id = ? AND name = ?",
                period.sheetId(), period.name());
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND period_name = ?",
                period.sheetId(), period.name());
    }

    private static Period period(ResultSet rs, int i) throws SQLException {
        return new Period(rs.getString("sheet_id"), rs.getString("name"), rs.getDate("from_date").toLocalDate(),
                rs.getDate("to_date").toLocalDate(), rs.getBoolean("closed"), rs.getBigDecimal("closed_total"),
                rs.getBoolean("soft"));
    }
}
# Add a period. Validate first so a bad name or dates is a 400 and writes nothing.
validate:
  class: net.officefloor.hq.app.period.ValidatePeriod
  next: save
# Refuses a name already used or dates overlapping another period of the sheet.
save:
  class: net.officefloor.hq.app.period.SavePeriod
  govern: [ transaction ]
  next: record
# Audit only once the period is saved: a refused one writes no line.
record:
  class: net.officefloor.hq.app.period.RecordPeriodAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithPeriod
  govern: [ transaction ]

